/* ---------- app ---------- */
/* ---------- occasion icons: flat shapes that take their colors from the palette ----------
   Each icon is drawn in a box about 40 units across, centered on 0,0. */
const P = (d, f) => `<path d="${d}" fill="${f}"/>`;
const ST = (d, col, w = 1.6) => `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const CI = (x, y, r, f) => `<circle cx="${x}" cy="${y}" r="${r}" fill="${f}"/>`;
const EL = (x, y, rx, ry, f, rot = 0) => `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${f}"${rot ? ` transform="rotate(${rot} ${x} ${y})"` : ""}/>`;
const RC = (x, y, w, h, f, r = 0) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${f}"/>`;
const HEART = "M0 -3.5 C-1 -10 -11 -10.5 -11 -4 C-11 1.5 -3.5 4.5 0 9 C3.5 4.5 11 1.5 11 -4 C11 -10.5 1 -10 0 -3.5Z";
const G = (x, y, k, rot, inner) => `<g transform="translate(${x} ${y}) rotate(${rot}) scale(${k})">${inner}</g>`;
const dk = (col, t = .3) => mix(col, "#000000", t), lt = (col, t = .45) => mix(col, "#ffffff", t);
