  // derby
  horseshoe:c => P("M-14 15 C-22 -3 -15 -19 0 -19 C15 -19 22 -3 14 15 L7.5 15 C13 0 9.5 -12 0 -12 C-9.5 -12 -13 0 -7.5 15Z", c.a)
    + [[-11.6,7],[-12,-3.5],[-6.2,-13.6],[6.2,-13.6],[12,-3.5],[11.6,7]].map(q => CI(q[0], q[1], 1.3, c.bg)).join(""),
  horse:c => P("M-2 20 C-3 11 -9 7 -14 2 C-17 -1 -20 -5 -18.5 -8.5 C-17 -11 -13.5 -9.5 -10.5 -10.5 C-8.5 -15.5 -3.5 -19.5 2.5 -19.5 L4.5 -26 L9 -18.5 C15.5 -13.5 18.5 -4.5 17.5 6 C17 11 16.5 15.5 16.5 20Z", c.ink)
    + CI(-5.5, -10.5, 1.5, c.bg) + ST("M8.5 -17.5 C13 -11.5 15 -4.5 14.2 4", c.bg, 1.3) + ST("M11.5 -9 C13 -4 13 1 12.5 5", c.bg, 1) + ST("M-18 -6.5 L-16 -5.6", c.bg, 1),
  derbyhat:c => EL(0, 8, 21, 6.5, c.a) + P("M-11.5 8 C-12 -9 12 -9 11.5 8Z", lt(c.a, .25)) + P("M-11.6 4 C-6 6.4 6 6.4 11.6 4 L11.5 8 C6 10 -6 10 -11.5 8Z", c.ink)
    + G(8, 3, .38, 0, wrose(0, 0, 20, c.c, 20)) + G(13.5, 6.5, .26, 0, wrose(0, 0, 20, c.b, 60)) + P("M3 1 Q-2 -4 -3 2 Q0 1 3 1Z", "#6f9a6a"),
  rose:c => wrose(0, 0, 17, c.c, 15) + P("M-13 9 Q-22 6 -20 16 Q-13 16 -13 9Z", "#6f9a6a") + P("M13 9 Q22 6 20 16 Q13 16 13 9Z", "#6f9a6a"),
  julep:c => P("M-9 -8 L-7 15 H7 L9 -8Z", lt(c.ink, .75)) + RC(-10, -10, 20, 3, lt(c.ink, .55), 1) + ST("M-8 -1 H8 M-7.5 6 H7.5", lt(c.ink, .5), 1)
    + P("M-2 -10 Q-9 -20 -1 -22 Q3 -16 -2 -10Z", "#6f9a6a") + P("M2 -10 Q10 -17 4 -22 Q-1 -17 2 -10Z", "#86a077") + ST("M6 -10 L12 -24", c.a, 1.6),
