  jockeycap:c => P("M-15 6 C-15 -12 9 -16 13 4Z", c.a) + P("M-15 6 C-13 -4 -9 -9 -4 -11.6 C-6 -5 -7 0 -7 5.4Z", c.c) + P("M1 -12 C5 -7 7 -1 7 4.6 L13 4 C12 -4 8 -10 1 -12Z", c.c) + P("M11 3 C17 2 23 5 25 9 C19 9 14 8 -15 7 V5Z", c.ink) + CI(-2, -13.4, 2.2, c.ink),
