/* ---------- occasion designs: each theme pairs a set of icons with a layout ---------- */
const put = (name, c, x, y, k, rot = 0) => `<g transform="translate(${n1(x)} ${n1(y)}) rotate(${n1(rot)}) scale(${+k.toFixed(3)})">${IC[name](c)}</g>`;
const mainFont = f => f === "script" ? {font:F.script, size:38} : f === "display" ? {font:F.display, size:31, ls:.05, upper:true} : {font:F.serif, size:30, weight:500};
const zoneSet = (ys, w, f) => ({
  top:{y:ys[0], w:w * .92, font:F.sans, size:11, ls:.28, upper:true},
  main:{y:ys[1], w, ...mainFont(f)},
  detail:{y:ys[2], w:w * .9, font:f === "script" ? F.serif : F.script, size:f === "script" ? 15 : 21, weight:500},
  msg:{y:ys[3], w:w * .88, font:F.serif, size:13, italic:true}});
const LAYOUTS = {
  // one large picture at the top, with a smaller one on each side
  emblem:{zones:f => zoneSet([.53, .68, .79, .875], .74, f),
    art:(ics, c) => frame(12, c.a, 1) + (ics[1] ? put(ics[1], c, W / 2 - 66 * S, .285 * H, 1.1 * S, -10) + put(ics[2] || ics[1], c, W / 2 + 66 * S, .285 * H, 1.1 * S, 10) : "") + put(ics[0], c, W / 2, .25 * H, 2.05 * S)},
  // pictures all the way around the edge
  ring:{zones:f => zoneSet([.345, .52, .655, .755], .58, f),
    art:(ics, c) => { const m = 27 * S, sp = 47 * S, nx = Math.max(3, Math.round((W - 2 * m) / sp)), ny = Math.max(2, Math.round((H - 2 * m) / sp)), r = rng(47), pts = [];
      for (let i = 0; i <= nx; i++){ pts.push([m + i * (W - 2 * m) / nx, m]); pts.push([m + i * (W - 2 * m) / nx, H - m]); }
      for (let j = 1; j < ny; j++){ pts.push([m, m + j * (H - 2 * m) / ny]); pts.push([W - m, m + j * (H - 2 * m) / ny]); }
      return pts.map((q, i) => put(ics[(i * 7 + (i >> 1)) % ics.length], c, q[0] + (r() - .5) * 6 * S, q[1] + (r() - .5) * 6 * S, (.82 + r() * .14) * S, r() * 30 - 15)).join(""); }},
  // a row of pictures along the bottom
  footer:{zones:f => zoneSet([.17, .35, .49, .59], .78, f),
    art:(ics, c) => { const n = wide() ? 7 : 5; let s = "";
      for (let i = 0; i < n; i++) s += put(ics[i % ics.length], c, W * (i + .5) / n, H - 35 * S, ics.length === 1 ? W / n / 45 : 1.18 * S, ics.length === 1 ? 0 : (i % 2 ? 6 : -6));
      return s; }},
  // an oval wreath of pictures around the words
  wreath:{zones:f => { const z = zoneSet([.36, .50, .61, .69], .1, f), w = () => W - 132 * S; z.main.w = w; z.top.w = () => w() * .86; z.detail.w = () => w() * .9; z.msg.w = () => w() * .78; return z; },
    art:(ics, c) => { const rx = W / 2 - 29 * S, ry = H / 2 - 28 * S, n = Math.max(10, Math.round(2 * Math.PI * Math.sqrt((rx * rx + ry * ry) / 2) / (45 * S))); let s = "";
      for (let i = 0; i < n; i++){ const a = -Math.PI / 2 + i * 2 * Math.PI / n; s += put(ics[i % ics.length], c, W / 2 + rx * Math.cos(a), H / 2 + ry * Math.sin(a), .84 * S, (i % 2 ? 10 : -10)); }
      return s; }},
  // a row of pictures along the top
  banner:{zones:f => zoneSet([.47, .625, .75, .84], .78, f),
    art:(ics, c) => { const n = wide() ? 7 : 5; let s = "";
      for (let i = 0; i < n; i++) s += put(ics[i % ics.length], c, W * (i + .5) / n, 36 * S, 1.18 * S, i % 2 ? 6 : -6);
      return s; }},
  // a column of pictures down each side
  sides:{zones:f => { const z = zoneSet([.33, .50, .63, .72], .1, f), w = () => W - 150 * S; z.main.w = w; z.top.w = () => w() * .9; z.detail.w = () => w() * .9; z.msg.w = () => w() * .86; return z; },
    art:(ics, c) => { let s = "";
      [.2, .5, .8].forEach((fy, i) => { s += put(ics[i % ics.length], c, 39 * S, fy * H, 1.16 * S, -6) + put(ics[(i + 1) % ics.length], c, W - 39 * S, fy * H, 1.16 * S, 6); });
      return s; }},
  // a cluster in two opposite corners
  corners:{zones:f => zoneSet([.36, .50, .62, .70], .5, f),
    art:(ics, c) => { const a = ics[0], b = ics[1] || ics[0], d = ics[2] || b;
      return put(a, c, 52 * S, 50 * S, 1.9 * S, -12) + put(b, c, 118 * S, 33 * S, 1.08 * S, 8) + put(d, c, 33 * S, 118 * S, 1.08 * S, -6)
           + put(a, c, W - 52 * S, H - 50 * S, 1.9 * S, 12) + put(b, c, W - 118 * S, H - 33 * S, 1.08 * S, -8) + put(d, c, W - 33 * S, H - 118 * S, 1.08 * S, 6); }}
};
